CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY, name text NOT NULL, available bigint NOT NULL DEFAULT 0 CHECK(available>=0), reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenants, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','merchant')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tokens(hash text PRIMARY KEY, kind text NOT NULL, user_id uuid REFERENCES users, data jsonb NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_configs(id uuid PRIMARY KEY, kind text NOT NULL, data jsonb NOT NULL, encrypted_key text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS provider_active ON provider_configs(kind) WHERE active;
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS sources(id uuid PRIMARY KEY, data jsonb NOT NULL, active boolean NOT NULL DEFAULT true, last_scheduled_at timestamptz, last_success_at timestamptz, last_error text);
CREATE TABLE IF NOT EXISTS posts(id text PRIMARY KEY, data jsonb NOT NULL, categories jsonb NOT NULL DEFAULT '[]', public boolean NOT NULL DEFAULT false, content_hash text NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS post_snapshots(id uuid PRIMARY KEY, post_id text NOT NULL REFERENCES posts, counters jsonb NOT NULL, fetched_at timestamptz NOT NULL, UNIQUE(post_id,fetched_at));
CREATE INDEX IF NOT EXISTS snapshot_recent ON post_snapshots(post_id,fetched_at DESC);
CREATE TABLE IF NOT EXISTS topic_imports(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, post_id text REFERENCES posts, status text NOT NULL DEFAULT 'queued', data jsonb NOT NULL DEFAULT '{}', error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS insights(post_id text NOT NULL REFERENCES posts, content_hash text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,content_hash));
CREATE TABLE IF NOT EXISTS matches(tenant_id uuid NOT NULL REFERENCES tenants, product_id uuid NOT NULL REFERENCES products, product_version integer NOT NULL, topic_hash text NOT NULL, data jsonb NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,product_id,product_version,topic_hash));
CREATE TABLE IF NOT EXISTS quotes(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, data jsonb NOT NULL, expires_at timestamptz NOT NULL, generation_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generations(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, product_id uuid NOT NULL REFERENCES products, preset text NOT NULL, status text NOT NULL DEFAULT 'queued', snapshot jsonb NOT NULL, copy_data jsonb NOT NULL DEFAULT '{"titles":[],"description":"","selling_points":[]}', copy_version integer NOT NULL DEFAULT 0, render_pending boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS idempotency(tenant_id uuid NOT NULL REFERENCES tenants, key text NOT NULL, quote_id uuid NOT NULL REFERENCES quotes, generation_id uuid NOT NULL REFERENCES generations, PRIMARY KEY(tenant_id,key));
CREATE TABLE IF NOT EXISTS generation_items(id uuid PRIMARY KEY, generation_id uuid NOT NULL REFERENCES generations, kind text NOT NULL, status text NOT NULL DEFAULT 'pending', credits bigint NOT NULL DEFAULT 0, quote_id uuid REFERENCES quotes, error text, selected_asset_id uuid, UNIQUE(generation_id,kind));
CREATE TABLE IF NOT EXISTS assets(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, product_id uuid REFERENCES products, generation_id uuid REFERENCES generations, item_id uuid REFERENCES generation_items, kind text NOT NULL, path text NOT NULL, original_path text, meta jsonb NOT NULL DEFAULT '{}', position integer NOT NULL DEFAULT 0, removed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS asset_product ON assets(tenant_id,product_id,kind);
CREATE TABLE IF NOT EXISTS provider_attempts(id uuid PRIMARY KEY, item_id uuid REFERENCES generation_items, generation_id uuid REFERENCES generations, provider_id uuid REFERENCES provider_configs, kind text NOT NULL, status text NOT NULL DEFAULT 'prepared', response_path text, request_id text, usage jsonb, estimated_cost numeric, actual_cost numeric, currency text, error text, duration_ms bigint, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE INDEX IF NOT EXISTS attempt_item ON provider_attempts(item_id,started_at DESC);
CREATE TABLE IF NOT EXISTS credit_ledger(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, generation_id uuid REFERENCES generations, item_id uuid REFERENCES generation_items, event_key text UNIQUE NOT NULL, type text NOT NULL, available_delta bigint NOT NULL, reserved_delta bigint NOT NULL, balance_after bigint NOT NULL, reserved_after bigint NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY, kind text NOT NULL, tenant_id uuid REFERENCES tenants, generation_id uuid REFERENCES generations, data jsonb NOT NULL DEFAULT '{}', dedupe_key text UNIQUE, status text NOT NULL DEFAULT 'queued', owner text, lease_until timestamptz, next_run_at timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS job_claim ON jobs(status,next_run_at,created_at);
CREATE TABLE IF NOT EXISTS resource_leases(resource text NOT NULL, slot integer NOT NULL, owner text NOT NULL, lease_until timestamptz NOT NULL, PRIMARY KEY(resource,slot));
CREATE TABLE IF NOT EXISTS worker_heartbeats(id text PRIMARY KEY, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS background_budgets(day date PRIMARY KEY, used integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY, user_id uuid REFERENCES users, action text NOT NULL, entity_id text, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
